// Coin images: usmint.gov

var coin = 0;
var zoom = 1;
var tzoom = 1;
var orient, torient;
var cpos, tpos;
var denominations = [100, 50, 25, 10, 5, 1];
var faces = [];
var places = [];
var coins = [];

function preload() {
	faces.push(loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/qhead.jpg'));
	faces.push(loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/qtails.jpg'));
	faces.push(loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/phead.jpg'));
	faces.push(loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/ptails.jpg'));
	faces.push(loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/nhead.jpg'));
	faces.push(loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/ntails.jpg'));
	faces.push(loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/dhead.jpg'));
	faces.push(loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/dtails.jpg'));
	faces.push(loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/hhead.jpg'));
	faces.push(loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/htails.jpg'));
	faces.push(loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/shead.jpg'));
	faces.push(loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/stails.jpg'));
}

function setup() {
	cnv = createCanvas(windowWidth, windowHeight, WEBGL);
	cnv.mouseClicked(advanceCoin);
	makePlaces();
	processImages();
	makeRims();
	makeHTML();
	setTimeout(nextCoins, 1000);
}

function makeHTML() {
	value = createP('');
	value.position(0, -height / 5);
	value.style('color', 'rgba(255,255,255,0.5)');
	value.style('fontSize', (height / 5) + 'px');
	slider = createSlider(0, 100, 0, 1);
	slider.position(10, height / 5);
	slider.style('width', height / 2.4 + 'px');
	slider.style('opacity', 0.5);
	slider.changed(slideToValue);
}

function makePlaces() {
	let sep = faces[0].height * 0.8;
	places.push([createVector(0, 0)]);
	places.push([createVector(-sep / 4, 0), createVector(sep / 4, 0)]);
	places.push([createVector(0, 0), createVector(-sep / 2, 0), createVector(sep / 2, 0)]);
	places.push([createVector(-sep / 3, 0), createVector(sep / 3, 0), createVector(0, -sep / 3), createVector(0, sep / 3)]);
	places.push([createVector(0, 0), createVector(-sep / 2, 0), createVector(sep / 2, 0), createVector(0, sep / 2), createVector(0, -sep / 2)]);
	places.push([createVector(0, 0), createVector(-sep / 2, 0), createVector(sep / 2, 0), createVector(-sep / 4, sep / 2), createVector(sep / 4, sep / 2), createVector(0, -sep / 2)]);
	places.push([createVector(0, 0), createVector(-sep / 2, 0), createVector(sep / 2, 0), createVector(-sep / 4, sep / 2), createVector(sep / 4, -sep / 2), createVector(sep / 3, sep / 2), createVector(-sep / 4, -sep / 2), createVector(0, -sep / 2)]);
	places.push([createVector(0, 0), createVector(-sep / 2, 0), createVector(sep / 2, 0), createVector(-sep / 4, sep / 2), createVector(sep / 2, -sep / 2), createVector(sep / 4, sep / 2), createVector(-sep / 2, -sep / 2), createVector(0, -sep / 2), createVector(0, sep / 2)]);
}

function processImages() {
	for (f of faces) {
		f.loadPixels();
		let x = 0;
		let y = 0;
		for (i = 0; i < f.pixels.length; i += 4) {
			if (dist(x, y, f.width / 2, f.height / 2) > (f.height / 2) * 0.98) f.pixels[i + 3] = 0;
			x += 1;
			if (x >= f.width) {
				x = 0;
				y += 1;
			}
		}
		f.updatePixels();
	}
}

function draw() {
	background(0);
	value.html('$' + nf(slider.value() / 100, 1, 2));
	scale(zoom);
	ambientLight(200);
	pointLight(120, 120, 120, 0, height, height / 2);
	tzoom = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 1.5, 0.2);
	zoom = lerp(zoom, tzoom, 0.1);
	metalness(10);
	shininess(5);
	for (c of coins) {
		c.torient.x = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0.2 * height, 0.8 * height, TAU, -TAU, true);
		c.torient.y = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0.2 * width, 0.8 * width, -TAU, TAU, true);
		c.move();
		c.show();
	}
}

function advanceCoin() {
	if (coin == 100) return;
	coin += 1;
	coin = constrain(coin, 0, 100);
	frameCount = 0;
	for (c of coins) {
		c.tpos.x = 2 * height / zoom;
	}
	setTimeout(nextCoins, 500);
}

function slideToValue() {
	coin = slider.value();
	frameCount = 0;
	for (c of coins) {
		c.tpos.x = 2 * height / zoom;
	}
	setTimeout(nextCoins, 500);
}

function nextCoins() {
	slider.value(coin);
	coins = [];
	clist = change(coin);
	let count = 0;
	for (c of clist) {
		for (i = 0; i < c[1]; i++) {
			count++;
		}
	}
	let cnum = 0;
	for (c of clist) {
		for (i = 0; i < c[1]; i++) {
			var x = places[count - 1][cnum].x;
			var y = places[count - 1][cnum].y;;
			let tpos = createVector(x, y, 0);
			coins.push(new Coin(c[0], tpos, count - cnum));
			cnum += 1;
		}
	}
}

//Adapted from: https://stackoverflow.com/questions/27854459/calculating-change-to-a-customer
function change(amount) {
	let res = [];
	for (i = 0; amount > 0 && i < denominations.length; i++) {
		res.push([denominations.length - i - 1])
		let value = denominations[i];
		if (value <= amount) {
			var count = Math.floor(amount / value);
			amount -= value * count;
			res[i].push(count);
		} else {
			res[i].push(0);
		}
	}
	return res;
}

